INSERT INTO TB_STK_HIST (PRD_CD, HIST_SEQ, CHG_TYPE, CHG_QTY, BF_STK_QTY, AF_STK_QTY, BF_RSV_QTY, AF_RSV_QTY,
                         ORD_NO, CHG_RSN, REG_DT, REG_ID)
SELECT #{PRD_CD}, NVL(MAX(HIST_SEQ), 0) + 1, #{CHG_TYPE}, #{CHG_QTY}, #{BF_STK_QTY}, #{AF_STK_QTY},
       #{BF_RSV_QTY}, #{AF_RSV_QTY}, #{ORD_NO}, #{CHG_RSN}, SYSDATE, #{REG_ID}
  FROM TB_STK_HIST
 WHERE PRD_CD = #{PRD_CD}
